A('10-e','Q10(e)','10D',[20],[31],'3-3','algebra-solving-equations','Water is pumped into a container through two pipes. For each pipe, the water is pumped at a constant rate. Pipe A can fill the container in 18 minutes. Pipe B can fill the container in 15 minutes. The container is empty. Water is then pumped into the container through the two pipes. After 5 minutes, Pipe A becomes blocked, so that water no longer comes in through Pipe A. Water continues to come in through Pipe B, until the container is full. Find the total length of time taken to fill the container. Give your answer in minutes and seconds. Hint: first find the fraction of the tank that each pipe fills in one minute.',['the fraction filled by both pipes in five minutes','the fraction left to fill after 5 minutes'])
assert len(p.cards)==40
selection_review=[
 {'pages':[3,4,16],'wording':'any five / any three questions','classification':'exam-level-selection','reason':'All ten questions retained for practice.'},
 {'pages':[10],'wording':'Use each letter only once','classification':'required-labels','reason':'All four labels form one 10-mark diagram task; none is optional.'},
 {'pages':[17],'wording':'or otherwise','classification':'method-choice','reason':'Alternative methods for the same roots, not alternative questions.'},
 {'pages':[22],'wording':'one possible value of k','classification':'open-answer','reason':'Any real k<−0.079; an open value, not a finite option pool.'},
 {'pages':[15],'wording':'if any','classification':'mathematical-condition','reason':'A possibly empty interval, not a choice of tasks.'},
]
def classify(c):
 t=c['context'].lower()
 if 'questions' in t and 'any' in t:return ('exam-level-selection','All questions retained irrespective of exam selection.')
 if 'otherwise' in t:return ('method-choice','Alternative methods for the same required task.')
 if 'possible value' in t:return ('open-answer','One freely chosen real k<−0.079, not a finite pool.')
 if 'either end' in t:return ('physical-context','Two walls at opposite ends of the table, not a task choice.')
 if 'if any' in t:return ('mathematical-condition','Possibly empty mathematical interval, not optional tasks.')
 return None
if __name__=='__main__':p.write(selection_review,classify)
